  const BUNDLE_NAME = "Kamishibai DSL 4.0 Runtime";
  const COMPONENT_IDS = ["kubohiroyakamishibairuntime4","kubohiroyaassetmanager","kubohiroyaasyncinput","kubohiroyabubble","kubohiroyaruntimeexpression","kubohiroyasvgtext","tmpose"];
